-- Reconcile exact product-local consumer brands for Weruva-hosted products.
--
-- The refreshed official Shopify inventory proves that BFF Best Feline
-- Friend, Cat Person, Cats in the Kitchen, Dogs in the Kitchen, Soulistic,
-- and TruLuxe are shelf-facing consumer brands, not interchangeable aliases
-- for the parent Weruva brand. This migration:
--   * repairs 108 exact serving/package rows tied to 104 one-to-one formulas;
--   * preserves four same-ingredient package variants as SKU children;
--   * creates three distinct formulas where consumer brand or ingredient
--     package version is a hard boundary;
--   * changes no ingredient statement or package image.
--
-- Evidence artifacts (sha256):
--   official manifest
--     8cdce682a7b8ba5d9d1be8cfdad0324e17110fbe1914233a38dd8f2361f18628
--   repair plan
--     7ca7e7c794cb257434ba03f0b2f4dc7bbde82e86454ecfe12c908ac63bf94cfa
--   bulk candidates
--     b2efede46b9d0cba0b4c6204957b9bb08cfc81d2ee40f32f8aa62045d440c14f
--   same-formula variants
--     0a681919ee750d4dc5f08b92aa340ec60c7bf93b9d25b809502a12c2109a6fe1
--   explicit splits
--     75c5023c6520827179e2e1193980131f262457ad7c0fa14dd1687976cb5c2e62
--   reviewed policy
--     863e940f08cd19495348d68b02595be62b9f566cc9e56f2ed17ddd0942449e06

CREATE TEMP TABLE tmp_weruva_brand_primary_targets (
  cache_key TEXT PRIMARY KEY,
  expected_brand TEXT NOT NULL,
  gtin TEXT NOT NULL,
  source_url TEXT NOT NULL,
  image_url TEXT NOT NULL,
  expected_live_ingredient_hash TEXT NOT NULL,
  source_captured_at TIMESTAMPTZ,
  source_content_hash TEXT
) ON COMMIT DROP;

INSERT INTO tmp_weruva_brand_primary_targets
SELECT *
FROM jsonb_to_recordset(
  convert_from(
    decode(
      '',
      'base64'
    ),
    'UTF8'
  )::JSONB
) AS payload(
  cache_key TEXT,
  expected_brand TEXT,
  gtin TEXT,
  source_url TEXT,
  image_url TEXT,
  expected_live_ingredient_hash TEXT,
  source_captured_at TIMESTAMPTZ,
  source_content_hash TEXT
);

CREATE TEMP TABLE tmp_weruva_same_formula_variants (
  cache_key TEXT PRIMARY KEY,
  canonical_cache_key TEXT NOT NULL,
  expected_brand TEXT NOT NULL,
  gtin TEXT NOT NULL,
  source_url TEXT NOT NULL,
  image_url TEXT NOT NULL,
  expected_live_ingredient_hash TEXT NOT NULL
) ON COMMIT DROP;

INSERT INTO tmp_weruva_same_formula_variants
SELECT *
FROM jsonb_to_recordset(
  convert_from(
    decode('', 'base64'),
    'UTF8'
  )::JSONB
) AS payload(
  cache_key TEXT,
  canonical_cache_key TEXT,
  expected_brand TEXT,
  gtin TEXT,
  source_url TEXT,
  image_url TEXT,
  expected_live_ingredient_hash TEXT
);

CREATE TEMP TABLE tmp_weruva_explicit_splits (
  cache_key TEXT PRIMARY KEY,
  canonical_cache_key TEXT,
  expected_brand TEXT NOT NULL,
  gtin TEXT NOT NULL,
  source_url TEXT NOT NULL,
  image_url TEXT NOT NULL,
  expected_live_ingredient_hash TEXT NOT NULL
) ON COMMIT DROP;

INSERT INTO tmp_weruva_explicit_splits
SELECT *
FROM jsonb_to_recordset(
  convert_from(
    decode('', 'base64'),
    'UTF8'
  )::JSONB
) AS payload(
  cache_key TEXT,
  canonical_cache_key TEXT,
  expected_brand TEXT,
  gtin TEXT,
  source_url TEXT,
  image_url TEXT,
  expected_live_ingredient_hash TEXT
);

DO $payload_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_brand_primary_targets) <> 104
     OR (SELECT count(*) FROM tmp_weruva_same_formula_variants) <> 4
     OR (SELECT count(*) FROM tmp_weruva_explicit_splits) <> 3
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand payload cardinality changed';
  END IF;

  IF (SELECT count(*) FROM tmp_weruva_brand_primary_targets WHERE expected_brand = 'BFF Best Feline Friend') <> 41
     OR (SELECT count(*) FROM tmp_weruva_brand_primary_targets WHERE expected_brand = 'Cat Person') <> 8
     OR (SELECT count(*) FROM tmp_weruva_brand_primary_targets WHERE expected_brand = 'Cats in the Kitchen') <> 11
     OR (SELECT count(*) FROM tmp_weruva_brand_primary_targets WHERE expected_brand = 'Dogs in the Kitchen') <> 5
     OR (SELECT count(*) FROM tmp_weruva_brand_primary_targets WHERE expected_brand = 'Soulistic') <> 29
     OR (SELECT count(*) FROM tmp_weruva_brand_primary_targets WHERE expected_brand = 'TruLuxe') <> 10
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand payload distribution changed';
  END IF;

  IF EXISTS (
    SELECT cache_key FROM (
      SELECT cache_key FROM tmp_weruva_brand_primary_targets
      UNION ALL SELECT cache_key FROM tmp_weruva_same_formula_variants
      UNION ALL SELECT cache_key FROM tmp_weruva_explicit_splits
    ) all_targets
    GROUP BY cache_key HAVING count(*) <> 1
  ) OR EXISTS (
    SELECT 1 FROM (
      SELECT expected_brand, gtin, source_url, image_url, expected_live_ingredient_hash
      FROM tmp_weruva_brand_primary_targets
      UNION ALL
      SELECT expected_brand, gtin, source_url, image_url, expected_live_ingredient_hash
      FROM tmp_weruva_same_formula_variants
      UNION ALL
      SELECT expected_brand, gtin, source_url, image_url, expected_live_ingredient_hash
      FROM tmp_weruva_explicit_splits
    ) target
    WHERE target.expected_brand NOT IN (
      'BFF Best Feline Friend', 'Cat Person', 'Cats in the Kitchen',
      'Dogs in the Kitchen', 'Soulistic', 'TruLuxe'
    )
       OR target.gtin !~ '^[0-9]{8,14}$'
       OR target.source_url !~ '^https://www[.]weruva[.]com/products/'
       OR target.image_url !~ '^https://cdn[.]shopify[.]com/'
       OR target.expected_live_ingredient_hash !~ '^[a-f0-9]{64}$'
  ) THEN
    RAISE EXCEPTION 'Weruva shelf-brand payload contains an unsafe identity';
  END IF;
END
$payload_guards$;

CREATE TEMP TABLE tmp_weruva_bulk_formula_map ON COMMIT DROP AS
SELECT
  target.*,
  serving.product_name,
  serving.product_line,
  serving.pet_type,
  COALESCE(NULLIF(lower(serving.life_stage), ''), 'unknown') AS life_stage,
  COALESCE(NULLIF(lower(serving.food_form), ''), 'unknown') AS food_form,
  COALESCE(serving.flavor, '') AS flavor,
  serving.package_size,
  serving.ingredient_text,
  serving.ingredients,
  formula.id AS formula_id,
  formula.formula_key AS old_formula_key,
  concat_ws(
    '|',
    split_part(formula.formula_key, '|', 1),
    lower(target.expected_brand),
    split_part(formula.formula_key, '|', 3),
    split_part(formula.formula_key, '|', 4),
    split_part(formula.formula_key, '|', 5),
    split_part(formula.formula_key, '|', 6),
    split_part(formula.formula_key, '|', 7),
    split_part(formula.formula_key, '|', 8)
  ) AS new_formula_key
FROM tmp_weruva_brand_primary_targets target
JOIN public.product_data serving
  ON serving.cache_key = target.cache_key
 AND lower(serving.brand) = 'weruva'
 AND regexp_replace(COALESCE(serving.gtin, ''), '\D', '', 'g') = target.gtin
 AND serving.source_url = target.source_url
 AND serving.image_url = target.image_url
 AND serving.formula_version_provenance->>'ingredient_text_hash' = target.expected_live_ingredient_hash
 AND encode(digest(
       public.catalog_normalize_ingredient_evidence(serving.ingredient_text),
       'sha256'
     ), 'hex') = target.expected_live_ingredient_hash
 AND serving.formula_evidence_tier = 'manufacturer_current_exact'
 AND serving.source_quality = 'manufacturer'
 AND serving.ingredient_verification_status = 'manufacturer'
 AND serving.image_verification_status = 'manufacturer'
 AND serving.is_complete_food
 AND serving.catalog_exclusion_reason IS NULL
JOIN public.catalog_formulas formula
  ON formula.source_url = serving.source_url
 AND formula.front_image_url = serving.image_url
 AND lower(formula.brand) = 'weruva'
 AND formula.pet_type = serving.pet_type
 AND formula.active
 AND formula.verification_status = 'verified'
 AND formula.formula_evidence_tier = 'manufacturer_current_exact'
 AND public.catalog_normalize_ingredient_evidence(formula.ingredient_text) =
     public.catalog_normalize_ingredient_evidence(serving.ingredient_text);

DO $bulk_formula_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_bulk_formula_map) <> 104
     OR (SELECT count(DISTINCT formula_id) FROM tmp_weruva_bulk_formula_map) <> 104
     OR (SELECT count(DISTINCT new_formula_key) FROM tmp_weruva_bulk_formula_map) <> 104
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand target lost its one-to-one formula';
  END IF;

  IF EXISTS (
    SELECT 1 FROM tmp_weruva_bulk_formula_map map
    JOIN public.catalog_formulas formula ON formula.id = map.formula_id
    WHERE formula.manufacturer <> 'weruva'
       OR array_length(string_to_array(map.old_formula_key, '|'), 1) <> 8
       OR split_part(map.old_formula_key, '|', 2) <> 'weruva'
       OR formula.promoted_cache_key IS NOT NULL
          AND formula.promoted_cache_key <> map.cache_key
       OR EXISTS (
         SELECT 1 FROM public.catalog_formulas other
         WHERE other.formula_key = map.new_formula_key
           AND other.id <> map.formula_id
       )
  ) THEN
    RAISE EXCEPTION 'Weruva shelf-brand formula collision detected';
  END IF;
END
$bulk_formula_guards$;

CREATE TEMP TABLE tmp_weruva_bulk_serving_map ON COMMIT DROP AS
SELECT
  map.cache_key,
  map.cache_key AS canonical_cache_key,
  map.expected_brand,
  map.gtin,
  map.source_url,
  map.image_url,
  map.expected_live_ingredient_hash,
  map.formula_id,
  TRUE AS primary_formula_serving
FROM tmp_weruva_bulk_formula_map map
UNION ALL
SELECT
  variant.cache_key,
  variant.canonical_cache_key,
  variant.expected_brand,
  variant.gtin,
  variant.source_url,
  variant.image_url,
  variant.expected_live_ingredient_hash,
  map.formula_id,
  FALSE
FROM tmp_weruva_same_formula_variants variant
JOIN tmp_weruva_bulk_formula_map map
  ON map.cache_key = variant.canonical_cache_key
 AND map.expected_brand = variant.expected_brand;

CREATE TEMP TABLE tmp_weruva_bulk_observation_map ON COMMIT DROP AS
SELECT
  serving_map.*,
  observation.id AS observation_id
FROM tmp_weruva_bulk_serving_map serving_map
JOIN public.product_data serving
  ON serving.cache_key = serving_map.cache_key
 AND lower(serving.brand) = 'weruva'
 AND regexp_replace(COALESCE(serving.gtin, ''), '\D', '', 'g') = serving_map.gtin
 AND serving.source_url = serving_map.source_url
 AND serving.image_url = serving_map.image_url
 AND serving.formula_version_provenance->>'ingredient_text_hash' = serving_map.expected_live_ingredient_hash
 AND encode(digest(
       public.catalog_normalize_ingredient_evidence(serving.ingredient_text),
       'sha256'
     ), 'hex') = serving_map.expected_live_ingredient_hash
 AND serving.formula_evidence_tier = 'manufacturer_current_exact'
 AND serving.source_quality = 'manufacturer'
 AND serving.ingredient_verification_status = 'manufacturer'
 AND serving.image_verification_status = 'manufacturer'
 AND serving.is_complete_food
 AND serving.catalog_exclusion_reason IS NULL
JOIN public.catalog_observations observation
  ON observation.formula_id = serving_map.formula_id
 AND observation.source_url = serving_map.source_url
 AND observation.front_image_url = serving_map.image_url
 AND regexp_replace(COALESCE(observation.gtin, ''), '\D', '', 'g') = serving_map.gtin
 AND observation.source_authority = 'manufacturer'
 AND observation.validation_status = 'accepted'
 AND observation.formula_evidence_tier = 'manufacturer_current_exact'
 AND encode(digest(
       public.catalog_normalize_ingredient_evidence(observation.ingredient_text),
       'sha256'
     ), 'hex') = serving_map.expected_live_ingredient_hash;

DO $bulk_child_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_bulk_serving_map) <> 108
     OR (SELECT count(*) FROM tmp_weruva_bulk_observation_map) <> 108
     OR (SELECT count(DISTINCT observation_id) FROM tmp_weruva_bulk_observation_map) <> 108
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand serving or observation cardinality changed';
  END IF;

  IF EXISTS (
    SELECT 1 FROM tmp_weruva_bulk_observation_map map
    WHERE (
      SELECT count(DISTINCT sku.formula_id)
      FROM public.catalog_skus sku
      WHERE sku.active
        AND regexp_replace(COALESCE(sku.gtin, ''), '\D', '', 'g') = map.gtin
    ) <> 1
       OR NOT EXISTS (
         SELECT 1 FROM public.catalog_skus sku
         WHERE sku.formula_id = map.formula_id
           AND sku.active
           AND regexp_replace(COALESCE(sku.gtin, ''), '\D', '', 'g') = map.gtin
       )
       OR NOT EXISTS (
         SELECT 1 FROM public.catalog_field_evidence evidence
         WHERE evidence.formula_id = map.formula_id
           AND evidence.source_url = map.source_url
           AND evidence.field_name = 'ingredient_text'
           AND evidence.accepted
       )
       OR NOT EXISTS (
         SELECT 1 FROM public.catalog_field_evidence evidence
         WHERE evidence.formula_id = map.formula_id
           AND evidence.source_url = map.source_url
           AND evidence.field_name = 'front_image_url'
           AND evidence.accepted
       )
  ) THEN
    RAISE EXCEPTION 'Weruva shelf-brand exact SKU or field evidence changed';
  END IF;
END
$bulk_child_guards$;

CREATE TEMP TABLE tmp_weruva_formula_alias_rekeys ON COMMIT DROP AS
SELECT
  alias.alias_formula_key AS old_alias_formula_key,
  concat_ws(
    '|',
    split_part(alias.alias_formula_key, '|', 1),
    lower(map.expected_brand),
    split_part(alias.alias_formula_key, '|', 3),
    split_part(alias.alias_formula_key, '|', 4),
    split_part(alias.alias_formula_key, '|', 5),
    split_part(alias.alias_formula_key, '|', 6),
    split_part(alias.alias_formula_key, '|', 7),
    split_part(alias.alias_formula_key, '|', 8)
  ) AS new_alias_formula_key,
  map.formula_id,
  map.expected_brand,
  map.source_url
FROM tmp_weruva_bulk_formula_map map
JOIN public.catalog_formula_aliases alias ON alias.formula_id = map.formula_id
WHERE split_part(alias.alias_formula_key, '|', 1) = 'weruva'
  AND split_part(alias.alias_formula_key, '|', 2) = 'weruva';

DO $formula_alias_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_formula_alias_rekeys) <> 7
     OR (SELECT count(DISTINCT new_alias_formula_key) FROM tmp_weruva_formula_alias_rekeys) <> 7
     OR EXISTS (
       SELECT 1 FROM tmp_weruva_formula_alias_rekeys rekey
       JOIN public.catalog_formula_aliases existing
         ON existing.alias_formula_key = rekey.new_alias_formula_key
       WHERE existing.formula_id <> rekey.formula_id
          OR existing.alias_formula_key <> rekey.old_alias_formula_key
     )
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand legacy formula alias collision detected';
  END IF;
END
$formula_alias_guards$;

UPDATE public.product_data serving
SET brand = map.expected_brand,
    food_form = CASE
      WHEN NULLIF(btrim(COALESCE(serving.food_form, '')), '') IS NULL THEN 'wet'
      ELSE serving.food_form
    END,
    formula_version_provenance = COALESCE(serving.formula_version_provenance, '{}'::JSONB)
      || jsonb_build_object(
        'weruva_shelf_brand_repair_20260804',
        jsonb_build_object(
          'status', 'exact_product_local_consumer_brand_repaired',
          'previous_brand', serving.brand,
          'consumer_brand', map.expected_brand,
          'canonical_formula_id', map.formula_id,
          'source_url', map.source_url,
          'ingredient_text_hash', map.expected_live_ingredient_hash,
          'ingredient_or_image_evidence_changed', FALSE,
          'reconciled_at', now()
        )
      ),
    updated_at = now()
FROM tmp_weruva_bulk_observation_map map
WHERE serving.cache_key = map.cache_key;

UPDATE public.catalog_formulas formula
SET brand = lower(map.expected_brand),
    formula_key = map.new_formula_key,
    identity_hash = encode(digest(map.new_formula_key, 'sha256'), 'hex'),
    promoted_cache_key = map.cache_key,
    promoted_at = COALESCE(formula.promoted_at, now()),
    protected_terms = ARRAY(
      SELECT DISTINCT lower(term)
      FROM unnest(COALESCE(formula.protected_terms, ARRAY[]::TEXT[]) || ARRAY[map.expected_brand]) term
      WHERE NULLIF(btrim(term), '') IS NOT NULL
      ORDER BY lower(term)
    ),
    formula_version_provenance = COALESCE(formula.formula_version_provenance, '{}'::JSONB)
      || jsonb_build_object(
        'weruva_shelf_brand_repair_20260804',
        jsonb_build_object(
          'status', 'exact_product_local_consumer_brand_repaired',
          'previous_formula_key', map.old_formula_key,
          'canonical_formula_key', map.new_formula_key,
          'consumer_brand', lower(map.expected_brand),
          'source_url', map.source_url,
          'ingredient_text_hash', map.expected_live_ingredient_hash,
          'ingredient_or_image_evidence_changed', FALSE,
          'reconciled_at', now()
        )
      ),
    updated_at = now()
FROM tmp_weruva_bulk_formula_map map
WHERE formula.id = map.formula_id;

UPDATE public.catalog_observations observation
SET brand = lower(map.expected_brand),
    food_form = CASE
      WHEN NULLIF(btrim(COALESCE(observation.food_form, '')), '') IS NULL THEN 'wet'
      ELSE observation.food_form
    END,
    raw_payload = COALESCE(observation.raw_payload, '{}'::JSONB)
      || jsonb_build_object(
        'consumer_brand_repair',
        jsonb_build_object(
          'status', 'exact_product_local_consumer_brand_repaired',
          'consumer_brand', lower(map.expected_brand),
          'source_url', map.source_url,
          'ingredient_text_hash', map.expected_live_ingredient_hash,
          'reconciled_at', now()
        )
      )
FROM tmp_weruva_bulk_observation_map map
WHERE observation.id = map.observation_id;

UPDATE public.catalog_formula_aliases alias
SET alias_formula_key = rekey.new_alias_formula_key,
    identity_hash = encode(digest(rekey.new_alias_formula_key, 'sha256'), 'hex'),
    source_url = rekey.source_url,
    metadata = COALESCE(alias.metadata, '{}'::JSONB)
      || jsonb_build_object(
        'weruva_shelf_brand_repair_20260804',
        jsonb_build_object(
          'previous_alias_formula_key', rekey.old_alias_formula_key,
          'consumer_brand', lower(rekey.expected_brand),
          'reconciled_at', now()
        )
      ),
    updated_at = now()
FROM tmp_weruva_formula_alias_rekeys rekey
WHERE alias.alias_formula_key = rekey.old_alias_formula_key;

INSERT INTO public.catalog_field_evidence (
  formula_id, observation_id, field_name, field_value, source_url,
  source_authority, accepted, observed_at, content_hash
)
SELECT
  map.formula_id,
  map.observation_id,
  'brand',
  to_jsonb(lower(map.expected_brand)),
  map.source_url,
  'manufacturer',
  TRUE,
  observation.observed_at,
  encode(digest(concat_ws(
    '|', map.formula_id::TEXT, 'brand', lower(map.expected_brand),
    map.source_url, map.expected_live_ingredient_hash
  ), 'sha256'), 'hex')
FROM tmp_weruva_bulk_observation_map map
JOIN public.catalog_observations observation ON observation.id = map.observation_id
ON CONFLICT (formula_id, field_name, source_url, content_hash) DO UPDATE
SET observation_id = EXCLUDED.observation_id,
    field_value = EXCLUDED.field_value,
    source_authority = EXCLUDED.source_authority,
    accepted = TRUE,
    observed_at = EXCLUDED.observed_at;

CREATE TEMP TABLE tmp_weruva_bulk_search_aliases ON COMMIT DROP AS
SELECT
  map.cache_key,
  map.gtin,
  map.expected_brand,
  CASE
    WHEN map.primary_formula_serving
      THEN concat_ws(' ', map.expected_brand, serving.product_name)
    ELSE concat_ws(' ', map.expected_brand, serving.product_name, serving.package_size)
  END AS alias_text,
  map.source_url,
  map.formula_id,
  map.expected_live_ingredient_hash
FROM tmp_weruva_bulk_observation_map map
JOIN public.product_data serving ON serving.cache_key = map.cache_key;

DO $bulk_search_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_bulk_search_aliases) <> 108
     OR (
       SELECT count(DISTINCT public.normalize_verified_product_search_query(alias_text))
       FROM tmp_weruva_bulk_search_aliases
     ) <> 108
     OR EXISTS (
       SELECT 1 FROM tmp_weruva_bulk_search_aliases expected
       JOIN public.catalog_verified_product_search_aliases existing
         ON existing.normalized_alias = public.normalize_verified_product_search_query(expected.alias_text)
        AND existing.active
       WHERE existing.cache_key <> expected.cache_key
     )
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand exact search alias collision detected';
  END IF;
END
$bulk_search_guards$;

INSERT INTO public.catalog_verified_product_search_aliases (
  cache_key, alias_text, normalized_alias, source_url, source_authority,
  evidence_observed_at, provenance, active, updated_at
)
SELECT
  alias.cache_key,
  alias.alias_text,
  public.normalize_verified_product_search_query(alias.alias_text),
  alias.source_url,
  'manufacturer',
  observation.observed_at,
  jsonb_build_object(
    'exact_formula_identity', TRUE,
    'formula_id', alias.formula_id,
    'consumer_brand_boundary', lower(alias.expected_brand),
    'ingredient_text_hash', alias.expected_live_ingredient_hash,
    'weruva_shelf_brand_repair_20260804', TRUE
  ),
  TRUE,
  now()
FROM tmp_weruva_bulk_search_aliases alias
JOIN tmp_weruva_bulk_observation_map map ON map.cache_key = alias.cache_key
JOIN public.catalog_observations observation ON observation.id = map.observation_id
ON CONFLICT (normalized_alias) WHERE active DO UPDATE
SET cache_key = EXCLUDED.cache_key,
    alias_text = EXCLUDED.alias_text,
    source_url = EXCLUDED.source_url,
    source_authority = EXCLUDED.source_authority,
    evidence_observed_at = EXCLUDED.evidence_observed_at,
    provenance = EXCLUDED.provenance,
    updated_at = now();

-- Three package identities require separate formulas: one cross-consumer-brand
-- Soulistic package and two Dogs in the Kitchen pouch ingredient versions.
CREATE TEMP TABLE tmp_weruva_split_source_map ON COMMIT DROP AS
SELECT
  target.*,
  serving.product_name,
  serving.product_line,
  serving.pet_type,
  COALESCE(NULLIF(lower(serving.life_stage), ''), 'unknown') AS life_stage,
  'wet' AS food_form,
  COALESCE(serving.flavor, '') AS flavor,
  serving.package_size,
  serving.ingredient_text,
  serving.ingredients,
  serving.ingredient_count,
  source_formula.id AS source_formula_id,
  source_formula.formula_key AS source_formula_key,
  source_formula.is_popular_brand,
  observation.id AS observation_id,
  observation.observed_at,
  CASE
    WHEN target.expected_brand = 'Soulistic' THEN
      concat_ws(
        '|',
        split_part(source_formula.formula_key, '|', 1),
        'soulistic',
        split_part(source_formula.formula_key, '|', 3),
        split_part(source_formula.formula_key, '|', 4),
        split_part(source_formula.formula_key, '|', 5),
        split_part(source_formula.formula_key, '|', 6),
        split_part(source_formula.formula_key, '|', 7),
        split_part(source_formula.formula_key, '|', 8)
      )
    ELSE 'manufacturer-package-version:' || encode(digest(concat_ws(
      '|', 'weruva', lower(target.expected_brand), target.gtin,
      target.source_url, target.expected_live_ingredient_hash
    ), 'sha256'), 'hex')
  END AS new_formula_key
FROM tmp_weruva_explicit_splits target
JOIN public.product_data serving
  ON serving.cache_key = target.cache_key
 AND lower(serving.brand) = 'weruva'
 AND regexp_replace(COALESCE(serving.gtin, ''), '\D', '', 'g') = target.gtin
 AND serving.source_url = target.source_url
 AND serving.image_url = target.image_url
 AND serving.formula_version_provenance->>'ingredient_text_hash' = target.expected_live_ingredient_hash
 AND encode(digest(
       public.catalog_normalize_ingredient_evidence(serving.ingredient_text),
       'sha256'
     ), 'hex') = target.expected_live_ingredient_hash
 AND serving.formula_evidence_tier = 'manufacturer_current_exact'
 AND serving.source_quality = 'manufacturer'
 AND serving.ingredient_verification_status = 'manufacturer'
 AND serving.image_verification_status = 'manufacturer'
 AND serving.is_complete_food
 AND serving.catalog_exclusion_reason IS NULL
JOIN public.catalog_skus sku
  ON sku.active
 AND regexp_replace(COALESCE(sku.gtin, ''), '\D', '', 'g') = target.gtin
JOIN public.catalog_formulas source_formula
  ON source_formula.id = sku.formula_id
 AND source_formula.active
 AND source_formula.verification_status = 'verified'
 AND source_formula.formula_evidence_tier = 'manufacturer_current_exact'
JOIN public.catalog_observations observation
  ON observation.formula_id = source_formula.id
 AND observation.source_url = target.source_url
 AND observation.front_image_url = target.image_url
 AND regexp_replace(COALESCE(observation.gtin, ''), '\D', '', 'g') = target.gtin
 AND observation.source_authority = 'manufacturer'
 AND observation.validation_status = 'accepted'
 AND observation.formula_evidence_tier = 'manufacturer_current_exact'
 AND encode(digest(
       public.catalog_normalize_ingredient_evidence(observation.ingredient_text),
       'sha256'
     ), 'hex') = target.expected_live_ingredient_hash;

DO $split_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_split_source_map) <> 3
     OR (SELECT count(DISTINCT cache_key) FROM tmp_weruva_split_source_map) <> 3
     OR (SELECT count(DISTINCT observation_id) FROM tmp_weruva_split_source_map) <> 3
     OR (SELECT count(DISTINCT new_formula_key) FROM tmp_weruva_split_source_map) <> 3
     OR EXISTS (
       SELECT 1 FROM tmp_weruva_split_source_map map
       WHERE EXISTS (
         SELECT 1 FROM public.catalog_formulas existing
         WHERE existing.formula_key = map.new_formula_key
       )
          OR (map.expected_brand = 'Soulistic'
              AND array_length(string_to_array(map.source_formula_key, '|'), 1) <> 8)
          OR (NULLIF(map.canonical_cache_key, '') IS NOT NULL
              AND NOT EXISTS (
                SELECT 1 FROM tmp_weruva_bulk_formula_map bulk
                WHERE bulk.cache_key = map.canonical_cache_key
                  AND bulk.formula_id = map.source_formula_id
                  AND bulk.expected_brand = map.expected_brand
              ))
          OR NOT EXISTS (
            SELECT 1 FROM public.catalog_field_evidence evidence
            WHERE evidence.formula_id = map.source_formula_id
              AND evidence.source_url = map.source_url
              AND evidence.field_name = 'ingredient_text'
              AND evidence.accepted
          )
          OR NOT EXISTS (
            SELECT 1 FROM public.catalog_field_evidence evidence
            WHERE evidence.formula_id = map.source_formula_id
              AND evidence.source_url = map.source_url
              AND evidence.field_name = 'front_image_url'
              AND evidence.accepted
          )
     )
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand explicit split baseline changed';
  END IF;

  IF EXISTS (
    SELECT 1 FROM tmp_weruva_split_source_map map
    JOIN public.catalog_formulas source_formula ON source_formula.id = map.source_formula_id
    WHERE public.catalog_normalize_ingredient_evidence(source_formula.ingredient_text) =
          public.catalog_normalize_ingredient_evidence(map.ingredient_text)
      AND map.expected_brand = 'Dogs in the Kitchen'
  ) OR EXISTS (
    SELECT 1 FROM tmp_weruva_split_source_map map
    JOIN public.catalog_formulas source_formula ON source_formula.id = map.source_formula_id
    WHERE public.catalog_normalize_ingredient_evidence(source_formula.ingredient_text) <>
          public.catalog_normalize_ingredient_evidence(map.ingredient_text)
      AND map.expected_brand = 'Soulistic'
  ) THEN
    RAISE EXCEPTION 'Weruva package-version or consumer-brand split evidence changed';
  END IF;
END
$split_guards$;

INSERT INTO public.catalog_formulas (
  formula_key, manufacturer, brand, product_name, product_line, pet_type,
  life_stage, food_form, flavor, diet_condition, is_complete_food,
  complete_food_evidence, ingredient_text, ingredients, front_image_url,
  source_url, source_authority, ingredient_verification_status,
  image_verification_status, protected_terms, verification_status, active,
  is_popular_brand, first_observed_at, last_observed_at, promoted_cache_key,
  promoted_at, identity_hash, formula_evidence_tier,
  formula_version_provenance, updated_at
)
SELECT
  map.new_formula_key,
  'weruva',
  lower(map.expected_brand),
  map.product_name,
  lower(COALESCE(NULLIF(map.product_line, ''), map.product_name)),
  map.pet_type,
  map.life_stage,
  map.food_form,
  lower(COALESCE(map.flavor, '')),
  '',
  TRUE,
  'Exact current official manufacturer product page and matching package image',
  map.ingredient_text,
  map.ingredients,
  map.image_url,
  map.source_url,
  'manufacturer',
  'manufacturer',
  'manufacturer',
  ARRAY(
    SELECT DISTINCT lower(term)
    FROM unnest(ARRAY[
      map.expected_brand, map.product_name, map.product_line,
      map.flavor, map.life_stage, map.food_form, 'pouch'
    ]) term
    WHERE NULLIF(btrim(term), '') IS NOT NULL
    ORDER BY lower(term)
  ),
  'verified',
  TRUE,
  map.is_popular_brand,
  map.observed_at,
  map.observed_at,
  map.cache_key,
  now(),
  encode(digest(map.new_formula_key, 'sha256'), 'hex'),
  'manufacturer_current_exact',
  jsonb_build_object(
    'source', 'weruva',
    'source_url', map.source_url,
    'captured_at', map.observed_at,
    'package_gtin', map.gtin,
    'package_size', map.package_size,
    'ingredient_text_hash', map.expected_live_ingredient_hash,
    'consumer_brand_boundary', lower(map.expected_brand),
    'package_version_boundary', map.expected_brand = 'Dogs in the Kitchen',
    'source_formula_id', map.source_formula_id,
    'ingredient_or_image_evidence_copied', FALSE,
    'weruva_shelf_brand_repair_20260804', TRUE
  ),
  now()
FROM tmp_weruva_split_source_map map;

CREATE TEMP TABLE tmp_weruva_split_map ON COMMIT DROP AS
SELECT source.*, target_formula.id AS target_formula_id
FROM tmp_weruva_split_source_map source
JOIN public.catalog_formulas target_formula
  ON target_formula.formula_key = source.new_formula_key
 AND target_formula.identity_hash = encode(digest(source.new_formula_key, 'sha256'), 'hex')
 AND target_formula.promoted_cache_key = source.cache_key
 AND target_formula.active
 AND target_formula.verification_status = 'verified';

DO $inserted_split_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_split_map) <> 3
     OR (SELECT count(DISTINCT target_formula_id) FROM tmp_weruva_split_map) <> 3
  THEN
    RAISE EXCEPTION 'Weruva shelf-brand split formulas were not created exactly';
  END IF;
END
$inserted_split_guards$;

UPDATE public.product_data serving
SET brand = map.expected_brand,
    food_form = 'wet',
    formula_version_provenance = COALESCE(serving.formula_version_provenance, '{}'::JSONB)
      || jsonb_build_object(
        'weruva_shelf_brand_repair_20260804',
        jsonb_build_object(
          'status', 'exact_formula_boundary_split',
          'previous_brand', serving.brand,
          'consumer_brand', map.expected_brand,
          'source_formula_id', map.source_formula_id,
          'canonical_formula_id', map.target_formula_id,
          'canonical_formula_key', map.new_formula_key,
          'ingredient_text_hash', map.expected_live_ingredient_hash,
          'ingredient_or_image_evidence_changed', FALSE,
          'reconciled_at', now()
        )
      ),
    updated_at = now()
FROM tmp_weruva_split_map map
WHERE serving.cache_key = map.cache_key;

UPDATE public.catalog_observations observation
SET formula_id = map.target_formula_id,
    brand = lower(map.expected_brand),
    food_form = 'wet',
    raw_payload = COALESCE(observation.raw_payload, '{}'::JSONB)
      || jsonb_build_object(
        'formula_boundary_split',
        jsonb_build_object(
          'source_formula_id', map.source_formula_id,
          'canonical_formula_id', map.target_formula_id,
          'consumer_brand', lower(map.expected_brand),
          'ingredient_text_hash', map.expected_live_ingredient_hash,
          'reconciled_at', now()
        )
      )
FROM tmp_weruva_split_map map
WHERE observation.id = map.observation_id;

UPDATE public.catalog_skus sku
SET formula_id = map.target_formula_id,
    updated_at = now()
FROM tmp_weruva_split_map map
WHERE sku.formula_id = map.source_formula_id
  AND sku.active
  AND regexp_replace(COALESCE(sku.gtin, ''), '\D', '', 'g') = map.gtin;

UPDATE public.catalog_field_evidence evidence
SET formula_id = map.target_formula_id,
    observation_id = COALESCE(evidence.observation_id, map.observation_id)
FROM tmp_weruva_split_map map
WHERE evidence.formula_id = map.source_formula_id
  AND evidence.source_url = map.source_url;

INSERT INTO public.catalog_field_evidence (
  formula_id, observation_id, field_name, field_value, source_url,
  source_authority, accepted, observed_at, content_hash
)
SELECT
  map.target_formula_id,
  map.observation_id,
  metadata.field_name,
  to_jsonb(metadata.field_value),
  map.source_url,
  'manufacturer',
  TRUE,
  map.observed_at,
  encode(digest(concat_ws(
    '|', map.new_formula_key, metadata.field_name, metadata.field_value,
    map.source_url, map.expected_live_ingredient_hash
  ), 'sha256'), 'hex')
FROM tmp_weruva_split_map map
CROSS JOIN LATERAL (VALUES
  ('brand', lower(map.expected_brand)),
  ('product_name', map.product_name),
  ('product_line', COALESCE(NULLIF(map.product_line, ''), map.product_name)),
  ('life_stage', map.life_stage),
  ('food_form', map.food_form),
  ('gtin', map.gtin),
  ('package_size', map.package_size)
) metadata(field_name, field_value)
ON CONFLICT (formula_id, field_name, source_url, content_hash) DO UPDATE
SET observation_id = EXCLUDED.observation_id,
    field_value = EXCLUDED.field_value,
    source_authority = EXCLUDED.source_authority,
    accepted = TRUE,
    observed_at = EXCLUDED.observed_at;

CREATE TEMP TABLE tmp_weruva_split_search_aliases ON COMMIT DROP AS
SELECT
  map.cache_key,
  concat_ws(' ', map.expected_brand, map.product_name, map.package_size) AS alias_text,
  map.source_url,
  map.observed_at,
  map.target_formula_id,
  map.expected_brand,
  map.expected_live_ingredient_hash
FROM tmp_weruva_split_map map;

DO $split_search_guards$
BEGIN
  IF (SELECT count(*) FROM tmp_weruva_split_search_aliases) <> 3
     OR (
       SELECT count(DISTINCT public.normalize_verified_product_search_query(alias_text))
       FROM tmp_weruva_split_search_aliases
     ) <> 3
     OR EXISTS (
       SELECT 1 FROM tmp_weruva_split_search_aliases expected
       JOIN public.catalog_verified_product_search_aliases existing
         ON existing.normalized_alias = public.normalize_verified_product_search_query(expected.alias_text)
        AND existing.active
       WHERE existing.cache_key <> expected.cache_key
     )
  THEN
    RAISE EXCEPTION 'Weruva explicit split search alias collision detected';
  END IF;
END
$split_search_guards$;

INSERT INTO public.catalog_verified_product_search_aliases (
  cache_key, alias_text, normalized_alias, source_url, source_authority,
  evidence_observed_at, provenance, active, updated_at
)
SELECT
  alias.cache_key,
  alias.alias_text,
  public.normalize_verified_product_search_query(alias.alias_text),
  alias.source_url,
  'manufacturer',
  alias.observed_at,
  jsonb_build_object(
    'exact_formula_identity', TRUE,
    'formula_id', alias.target_formula_id,
    'consumer_brand_boundary', lower(alias.expected_brand),
    'ingredient_text_hash', alias.expected_live_ingredient_hash,
    'package_version_boundary', alias.expected_brand = 'Dogs in the Kitchen',
    'weruva_shelf_brand_repair_20260804', TRUE
  ),
  TRUE,
  now()
FROM tmp_weruva_split_search_aliases alias
ON CONFLICT (normalized_alias) WHERE active DO UPDATE
SET cache_key = EXCLUDED.cache_key,
    alias_text = EXCLUDED.alias_text,
    source_url = EXCLUDED.source_url,
    source_authority = EXCLUDED.source_authority,
    evidence_observed_at = EXCLUDED.evidence_observed_at,
    provenance = EXCLUDED.provenance,
    updated_at = now();

DO $postconditions$
DECLARE
  target RECORD;
  v_top_cache TEXT;
  v_barcode_count INTEGER;
  v_barcode_cache TEXT;
BEGIN
  IF (
    SELECT count(*) FROM tmp_weruva_bulk_observation_map map
    JOIN public.product_data serving
      ON serving.cache_key = map.cache_key
     AND serving.brand = map.expected_brand
     AND regexp_replace(COALESCE(serving.gtin, ''), '\D', '', 'g') = map.gtin
     AND serving.source_url = map.source_url
     AND serving.image_url = map.image_url
     AND encode(digest(
           public.catalog_normalize_ingredient_evidence(serving.ingredient_text),
           'sha256'
         ), 'hex') = map.expected_live_ingredient_hash
  ) <> 108 THEN
    RAISE EXCEPTION 'Weruva bulk serving postcondition failed';
  END IF;

  IF (
    SELECT count(*) FROM tmp_weruva_bulk_formula_map map
    JOIN public.catalog_formulas formula
      ON formula.id = map.formula_id
     AND formula.formula_key = map.new_formula_key
     AND formula.identity_hash = encode(digest(map.new_formula_key, 'sha256'), 'hex')
     AND formula.brand = lower(map.expected_brand)
     AND formula.promoted_cache_key = map.cache_key
     AND formula.active
     AND formula.verification_status = 'verified'
     AND formula.formula_evidence_tier = 'manufacturer_current_exact'
     AND encode(digest(
           public.catalog_normalize_ingredient_evidence(formula.ingredient_text),
           'sha256'
         ), 'hex') = map.expected_live_ingredient_hash
  ) <> 104 THEN
    RAISE EXCEPTION 'Weruva bulk formula postcondition failed';
  END IF;

  IF (
    SELECT count(*) FROM tmp_weruva_bulk_observation_map map
    JOIN public.catalog_observations observation
      ON observation.id = map.observation_id
     AND observation.formula_id = map.formula_id
     AND observation.brand = lower(map.expected_brand)
     AND observation.source_url = map.source_url
  ) <> 108
     OR (SELECT count(*) FROM tmp_weruva_formula_alias_rekeys rekey
         JOIN public.catalog_formula_aliases alias
           ON alias.alias_formula_key = rekey.new_alias_formula_key
          AND alias.formula_id = rekey.formula_id) <> 7
  THEN
    RAISE EXCEPTION 'Weruva bulk observation or alias postcondition failed';
  END IF;

  IF (
    SELECT count(*) FROM tmp_weruva_split_map map
    JOIN public.product_data serving
      ON serving.cache_key = map.cache_key
     AND serving.brand = map.expected_brand
     AND serving.food_form = 'wet'
     AND serving.source_url = map.source_url
     AND serving.image_url = map.image_url
     AND encode(digest(
           public.catalog_normalize_ingredient_evidence(serving.ingredient_text),
           'sha256'
         ), 'hex') = map.expected_live_ingredient_hash
    JOIN public.catalog_formulas formula
      ON formula.id = map.target_formula_id
     AND formula.formula_key = map.new_formula_key
     AND formula.brand = lower(map.expected_brand)
     AND formula.promoted_cache_key = map.cache_key
     AND formula.source_url = map.source_url
     AND formula.front_image_url = map.image_url
     AND formula.active
     AND formula.verification_status = 'verified'
     AND encode(digest(
           public.catalog_normalize_ingredient_evidence(formula.ingredient_text),
           'sha256'
         ), 'hex') = map.expected_live_ingredient_hash
    JOIN public.catalog_observations observation
      ON observation.id = map.observation_id
     AND observation.formula_id = map.target_formula_id
     AND observation.brand = lower(map.expected_brand)
    JOIN public.catalog_skus sku
      ON sku.formula_id = map.target_formula_id
     AND sku.active
     AND regexp_replace(COALESCE(sku.gtin, ''), '\D', '', 'g') = map.gtin
  ) <> 3 THEN
    RAISE EXCEPTION 'Weruva explicit split postcondition failed';
  END IF;

  IF EXISTS (
    SELECT 1 FROM tmp_weruva_split_map map
    WHERE NOT EXISTS (
      SELECT 1 FROM public.catalog_formulas source_formula
      WHERE source_formula.id = map.source_formula_id
        AND source_formula.active
        AND source_formula.verification_status = 'verified'
    ) OR NOT EXISTS (
      SELECT 1 FROM public.catalog_skus source_sku
      WHERE source_sku.formula_id = map.source_formula_id AND source_sku.active
    ) OR NOT EXISTS (
      SELECT 1 FROM public.catalog_observations source_observation
      WHERE source_observation.formula_id = map.source_formula_id
        AND source_observation.source_authority = 'manufacturer'
        AND source_observation.validation_status = 'accepted'
    )
  ) THEN
    RAISE EXCEPTION 'Weruva source formula lost its retained exact package';
  END IF;

  FOR target IN
    SELECT
      alias.cache_key,
      map.canonical_cache_key AS expected_barcode_cache_key,
      alias.gtin,
      alias.alias_text
    FROM tmp_weruva_bulk_search_aliases alias
    JOIN tmp_weruva_bulk_observation_map map USING (cache_key)
    UNION ALL
    SELECT
      split.cache_key,
      split.cache_key AS expected_barcode_cache_key,
      split.gtin,
      alias.alias_text
    FROM tmp_weruva_split_map split
    JOIN tmp_weruva_split_search_aliases alias USING (cache_key)
  LOOP
    SELECT searched.cache_key INTO v_top_cache
    FROM public.search_verified_products(target.alias_text, 5) searched
    ORDER BY searched.rank DESC, searched.cache_key
    LIMIT 1;
    IF v_top_cache IS DISTINCT FROM target.cache_key THEN
      RAISE EXCEPTION 'Weruva exact shelf-brand search failed for %, got %', target.cache_key, v_top_cache;
    END IF;

    SELECT count(*), min(resolved.cache_key)
    INTO v_barcode_count, v_barcode_cache
    FROM public.resolve_verified_product_by_gtin(target.gtin, 8) resolved;
    IF v_barcode_count <> 1
       OR v_barcode_cache IS DISTINCT FROM target.expected_barcode_cache_key
    THEN
      RAISE EXCEPTION 'Weruva exact shelf-brand GTIN failed for %, count %, cache %', target.gtin, v_barcode_count, v_barcode_cache;
    END IF;
  END LOOP;
END
$postconditions$;
